<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
security_headers();student_private_headers();
$db=database();$student=student_account_current($db);if(!$student){header('Location: /aluno/login.php?next=%2Faluno%2Fcaderno.php',true,303);exit;}$studentId=(int)$student['id'];
$ids=array_values(array_unique(array_filter(array_map('intval',(array)($_GET['id']??$_POST['compare_id']??[])),static fn(int $id): bool=>$id>0)));if(count($ids)>2)$ids=array_slice($ids,0,2);
$allRecords=student_process_records_for_student($db,$studentId);$recordMap=[];foreach($allRecords as $item)$recordMap[(int)$item['id']]=$item;
foreach($ids as $id)if(!isset($recordMap[$id])){http_response_code(404);exit('Registro não encontrado.');}
$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!verify_csrf('student-research-compare',$_POST['_csrf']??null))$error='Solicitação inválida.';
    else try{
        $action=(string)($_POST['action']??'');
        if($action!=='fork')throw new RuntimeException('Ação inválida.');
        $baseId=(int)($_POST['source_test_id']??0);if(!in_array($baseId,$ids,true))throw new RuntimeException('Escolha um dos registros comparados como base.');
        $intent=(string)($_POST['research_intent']??'');$created=student_research_fork($db,$baseId,$studentId,$intent);$base=$recordMap[$baseId];
        $_SESSION['student_process_notice']='Próxima variação criada a partir de “'.(string)$base['title'].'”. Intenção: '.(string)$created['research_intent'].' Revise a exposição antes de continuar.';
        header('Location: /aluno/teste.php?id='.(int)$created['id'].'&view=exposure',true,303);exit;
    }catch(Throwable $e){$error=$e->getMessage();}
}
student_shell_start('Comparar experimentações',null,$student);?>
<div class="student-appbar"><a class="student-back" href="/aluno/caderno.php">← Caderno de Processos</a></div>
<p class="student-kicker">Comparação</p><h1 class="student-title">Comparar experimentações</h1><p class="student-lead">Veja o que foi registrado de modo diferente e leia essas diferenças junto com os resultados. A comparação descreve os registros; não atribui causa ao resultado.</p>
<?php if($error!==''):?><p class="ui-alert ui-alert-error" role="alert"><?=h($error)?></p><?php endif;?>
<?php if(count($allRecords)<2):?>
<section class="student-section"><div class="student-empty"><strong>São necessários dois registros.</strong><p>Crie outra experimentação no Caderno para poder comparar.</p><a class="button button-primary" href="/aluno/caderno.php">Voltar ao Caderno</a></div></section>
<?php elseif(count($ids)<2):?>
<section class="student-section student-research-picker" aria-labelledby="compare-pick-title"><div class="student-section-heading"><div><p class="student-kicker">Escolha</p><h2 class="student-subtitle" id="compare-pick-title"><?=count($ids)===1?'Escolha o segundo registro':'Escolha dois registros'?></h2></div><p>Use dois registros que façam sentido lado a lado para a pergunta que você quer investigar.</p></div>
<form method="get" class="student-research-picker-form">
<?php if(count($ids)===1):$base=$recordMap[$ids[0]];?><input type="hidden" name="id[]" value="<?=(int)$base['id']?>"><article class="student-research-picked"><span class="student-card-label">Registro A</span><h3><?=h((string)$base['title'])?></h3><p><?=h((string)($base['test_date']?:'Sem data'))?> · <?=h((string)(($base['context_scope']??'course')==='personal'?'Pessoal':$base['public_title'].' · '.$base['cohort_title']))?></p></article><label class="form-field">Registro B<select name="id[]" required><option value="">Escolha…</option><?php foreach($allRecords as $candidate):if((int)$candidate['id']===(int)$base['id'])continue;?><option value="<?=(int)$candidate['id']?>"><?=h((string)$candidate['title'])?> · <?=h((string)($candidate['test_date']?:'sem data'))?></option><?php endforeach;?></select></label>
<?php else:?><label class="form-field">Registro A<select name="id[]" required><option value="">Escolha…</option><?php foreach($allRecords as $candidate):?><option value="<?=(int)$candidate['id']?>"><?=h((string)$candidate['title'])?> · <?=h((string)($candidate['test_date']?:'sem data'))?></option><?php endforeach;?></select></label><label class="form-field">Registro B<select name="id[]" required><option value="">Escolha…</option><?php foreach($allRecords as $candidate):?><option value="<?=(int)$candidate['id']?>"><?=h((string)$candidate['title'])?> · <?=h((string)($candidate['test_date']?:'sem data'))?></option><?php endforeach;?></select></label><?php endif;?><div class="student-actions"><button class="button button-primary" type="submit">Comparar registros</button></div></form></section>
<?php else:
$a=$recordMap[$ids[0]];$b=$recordMap[$ids[1]];$stepsA=student_process_steps($db,(int)$a['id']);$stepsB=student_process_steps($db,(int)$b['id']);$differences=student_research_difference_rows($a,$b,$stepsA,$stepsB);$exposureRows=student_research_exposure_rows($a,$b);$resultMediaA=student_test_media_by_phase(student_test_media($db,(int)$a['id']),'result');$resultMediaB=student_test_media_by_phase(student_test_media($db,(int)$b['id']),'result');?>
<section class="student-section student-research-differences" aria-labelledby="research-differences-title"><div class="student-section-heading"><div><p class="student-kicker">O que mudou</p><h2 class="student-subtitle" id="research-differences-title">Diferenças registradas</h2></div><p>Somente campos comparáveis que realmente mudaram aparecem aqui.</p></div>
